from typing import List
from operator import add


class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        if k == 1:
            return max(max(stayScore[0]), max(travelScore[0]))
        columns = [list(col) for col in zip(*travelScore)]
        dp = [0] * n
        for day in range(k):
            stay = stayScore[day]
            dp = [max(dp[d] + stay[d], max(map(add, dp, columns[d]))) for d in range(n)]
        return max(dp)
